package com.google.gson.stream;

import com.google.gson.internal.JsonReaderInternalAccess;
import com.google.gson.internal.bind.JsonTreeReader;
import com.google.gson.stream.JsonReader;
import java.io.*;
import java.io.Closeable;
import java.io.EOFException;
import java.io.IOException;
import java.io.Reader;
import java.io.StringReader;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

public class JsonReader_nextInt_TriageGen0Test {

    @Test
    public void testNextInt_Normal() throws IOException {
        JsonReader reader = new JsonReader(new StringReader("42"));
        assertEquals(42, reader.nextInt());
    }

    @Test
    public void testNextInt_Negative() throws IOException {
        JsonReader reader = new JsonReader(new StringReader("-42"));
        assertEquals(-42, reader.nextInt());
    }

    @Test
    public void testNextInt_Zero() throws IOException {
        JsonReader reader = new JsonReader(new StringReader("0"));
        assertEquals(0, reader.nextInt());
    }

    @Test
    public void testNextInt_ParseError() throws IOException {
        JsonReader reader = new JsonReader(new StringReader("abc"));
        assertThrows(NumberFormatException.class, () -> reader.nextInt());
    }

    @Test
    public void testNextInt_Overflow() throws IOException {
        JsonReader reader = new JsonReader(new StringReader("2147483648"));
        assertThrows(NumberFormatException.class, () -> reader.nextInt());
    }

    @Test
    public void testNextInt_PrecisionLost() throws IOException {
        JsonReader reader = new JsonReader(new StringReader("12345678901234567890.12345678901234567890"));
        assertThrows(NumberFormatException.class, () -> reader.nextInt());
    }

    @Test
    public void testNextInt_PeekedNone() throws IOException {
        JsonReader reader = new JsonReader(new StringReader(""));
        reader.peek();
        assertEquals(0, reader.nextInt());
    }

    @Test
    public void testNextInt_PeekedLong() throws IOException {
        JsonReader reader = new JsonReader(new StringReader("12345678901234567890"));
        assertEquals(BigInteger.valueOf(12345678901234567890L).intValue(), reader.nextInt());
    }

    @Test
    public void testNextInt_PeekedNumber() throws IOException {
        JsonReader reader = new JsonReader(new StringReader("1234567890"));
        assertEquals(1234567890, reader.nextInt());
    }

    @Test
    public void testNextInt_PeekedSingleQuoted() throws IOException {
        JsonReader reader = new JsonReader(new StringReader("'1234567890"));
        assertEquals(1234567890, reader.nextInt());
    }

    @Test
    public void testNextInt_PeekedDoubleQuoted() throws IOException {
        JsonReader reader = new JsonReader(new StringReader("\"1234567890"));
        assertEquals(1234567890, reader.nextInt());
    }

    @Test
    public void testNextInt_PeekedBuffered() throws IOException {
        JsonReader reader = new JsonReader(new StringReader("1234567890.1234567890"));
        assertEquals(1234567890, reader.nextInt());
    }

    @Test
    public void testNextInt_SetLenient() throws IOException {
        JsonReader reader = new JsonReader(new StringReader("1234567890.1234567890"));
        reader.setLenient(true);
        assertEquals(1234567890, reader.nextInt());
    }
}
